if(Test-Path $out){Remove-Item $out -Force};$zip=[System.IO.Compression.ZipFile]::Open($out,[System.IO.Compression.ZipArchiveMode]::Create);function Entry([string]$name,[string]$content){$e=$zip.CreateEntry($name);$w=New-Object IO.StreamWriter($e.Open(),[Text.UTF8Encoding]::new($false));$w.Write($content);$w.Dispose()};Entry '[Content_Types].xml' $ct;Entry '_rels/.rels' $rels;Entry 'word/document.xml' $document;Entry 'word/styles.xml' $styles;Entry 'word/_rels/document.xml.rels' $wrels;foreach($img in Get-ChildItem (Join-Path $root 'docs\figures\*.png')){$e=$zip.CreateEntry('word/media/'+$img.Name);$src=[IO.File]::OpenRead($img.FullName);$dst=$e.Open();$src.CopyTo($dst);$src.Dispose();$dst.Dispose()};$zip.Dispose();Remove-Item $tmp -Recurse -Force;Write-Output ('SAVED '+$out)
